#!/usr/bin/env python3
"""Build original Persian working drafts from an explicitly indexed recipe-title inventory.

The collection links are discovery evidence ONLY, NOT evidence that the independently
created weights/instructions match the publisher's original recipe. Each entry remains
'draft'; the production release gate requires human review.
"""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
source=root/'content/researched-recipes.psv'
target=root/'src/data/researchedRecipes.ts'
special={}
for line in (root/'content/culinary-specific-steps.psv').read_text(encoding='utf-8').splitlines():
 if line.strip() and not line.startswith('#'):
  title,body=line.split('|',1)
  special[title]=body.split('~')
S={
 'chi':'https://chishi.ir/20064-ghaza-irani/',
 'beq':'https://chishi.ir/15234-khoresh-gheyme-beh/',
 'bush':'https://chishi.ir/3979-gheyme-boushehri/',
 'carrot':'https://chishi.ir/26314-kotlet-morgh-havij/',
 'bean':'https://chishi.ir/23232-kotlet-loobia-sabz/',
 'pate':'https://chishi.ir/28246-bakele-pate/',
 'tah':'https://chishi.ir/20003-tahchin-baghali-polo-mahiche/',
 'sosis':'https://chishi.ir/13692-kookoo-sosis/',
 'tabe':'https://chishi.ir/13152-kabab-tabe-kete-ghalebi/',
}
for key,segment in {
 'quickch':'quick-chicken-recipes','chicken':'chicken-recipes',
 'familych':'family-chicken-recipes','onepot':'one-pot-recipes',
 'pasta':'pasta-recipes','vegpasta':'vegetarian-pasta-recipes',
 'veg':'easy-vegetarian-recipes','quickveg':'quick-veggie-recipes',
 'vegsoup':'vegetarian-soup-recipes','healthylunch':'healthy-lunch-recipes',
 'veglunch':'healthy-vegetarian-lunch-recipes','lowcal':'low-calorie-lunch-recipes',
 'salad':'salad-recipes','pastasalad':'pasta-salad-recipes',
 'packlunch':'healthy-packed-lunch-recipes','sandwich':'sandwich-recipes',
 'fish':'easy-fish-recipes','fishrecipes':'fish','breakfast':'breakfast-recipes',
 'quickbreak':'quick-breakfast-recipes','lowsalt':'low-salt-lunch-recipes',
 'snack':'snack-recipes','quickcurry':'quick-curry-recipes',
}.items(): S[key]='https://tollbit.bbcgoodfood.com/recipes/collection/'+segment
rows=[]
for number,line in enumerate(source.read_text(encoding='utf-8').splitlines(),1):
 if not line.strip() or line.lstrip().startswith('#'):continue
 fields=line.split('|')
 if len(fields)!=8:raise ValueError(f'Line {number}, required 8 columns, got {len(fields)}')
 title,cats,prep,cook,ingredients,mode,sourceKey,reference=fields
 if sourceKey not in S:raise ValueError(f'Line {number}: unknown source {sourceKey}')
 if mode not in ['rice','stew','roast','skillet','soup','bake','fritter','pasta','wrap','salad','curry','pie','bowl','noodle','sandwich','egg','fish','snack']:
  raise ValueError(f'Line {number}: invalid cooking method')
 if not cats or not set(cats)<=set('ilsf'):raise ValueError(f'Line {number}: categories')
 if title.strip()!=title:raise ValueError(f'Line {number}: trim title')
 for ing in ingredients.split(','):
  k,amount=ing.split('/');assert float(amount)>0,(number,ing)
 rows.append((title,cats,int(prep),int(cook),ingredients,mode,S[sourceKey],reference))
assert len(rows)>=174, f'Too few sourced distinct titles: {len(rows)}'
# JSON strings are safe to embed as TS literal because there are no expressions.
payload='\n'.join('|'.join([title,cats,str(prep),str(cook),ings,mode,url,ref]) for title,cats,prep,cook,ings,mode,url,ref in rows)
header='''// Generated by scripts/compile_research_recipes.py — edit content/researched-recipes.psv, not this file.
// Publisher indexes establish that a dish name exists; our quantities/instructions are independent
// EDITORIAL DRAFTS and are NOT a checked transcription or a culinary review of source recipes.
import type {Category,Recipe,RecipeIngredient,Unit} from '../domain/types';
import {BY_ID} from './ingredients';
const ROWS = '''+json.dumps(payload,ensure_ascii=False)+''';
const SPECIAL:Record<string,string[]> = '''+json.dumps(special,ensure_ascii=False)+''' ;
const C:Record<string,Category>={i:'iranian',l:'light',s:'snack',f:'fastfood'};
const fluids=new Set(['water','milk','oil','olive_oil','lemon_juice','chicken_stock','beef_broth','rosewater','vinegar','apple_vinegar','coconut_milk','soy_sauce','sesame_oil','ghee','maple_syrup','date_syrup','lime_juice']);
const units=new Set(['egg','banana','apple','dates','orange','pear','lime','mango','pineapple','quince','peach','apricot','fig']);
const say=(id:string):string=>BY_ID.get(id)?.fa??id;
function makeSteps(mode:string,ings:RecipeIngredient[],title:string):Recipe['steps']{
 const primary=ings[0]!; const second=ings[1]!;
 const first=say(primary.ingredientId); const other=say(second.ingredientId);
 const grain=ings.find(i=>['rice','pasta','macaroni','orzo','quinoa','couscous','bulgur','gnocchi','lasagna','rice_noodles','red_lentil','lentil'].includes(i.ingredientId));
 const animal=ings.find(i=>['chicken','chicken_leg','chicken_thigh','chicken_mince','ground_beef','ground_lamb','ground_turkey','lamb','beef','fish','white_fish','salmon','cod','shrimp','sardine'].includes(i.ingredientId));
 const legumes=ings.filter(i=>['kidney_bean','black_bean','white_bean','bean','fava_bean','split_pea','chickpea','red_lentil','lentil','mung_bean','butter_bean'].includes(i.ingredientId));
 let preface='مواد لازم را وزن کن، سبزیجات را بشوی و خشک کن و مواد خام و پخته را در ظرف‌های جدا قرار بده.';
 if(grain)preface+=` ${say(grain.ingredientId)} را مطابق نیاز دستور بشوی یا برای پخت آماده کن.`;
 if(legumes.length)preface+=' حبوبات خشک را از پیش بخیسان، آب خیساندن را دور بریز و در آب تازه کاملاً بپز؛ کنسروی‌ها را آبکش کن.';
 if(animal)preface+=' برای مواد پروتئینی خام، تخته و چاقوی جداگانه استفاده کن.';
 const selected:Record<string,[string,string,string]>= {
 rice:[`پیاز و چاشنی‌های دستور را با حرارت متوسط آماده کن و ${first} و ${other} را طبق ماهیتشان جداگانه بپز یا نیم‌پز کن.`,`برنج یا غله را با مواد پخته لایه‌لایه ترکیب کن و آب را تدریجی تنظیم کن تا غذا شفته نشود.`,`با شعله ملایم و درِ بسته بگذار مغز دانه‌ها بپزد؛ پیش از سرو، مواد پروتئینی را از نظر پخت کامل بررسی کن.`],
 stew:[`پیاز و ترکیبات معطر را کمی تفت بده و ${first} را اضافه کن؛ اگر حبوبات یا گوشت دارد آن‌ها را جدا آماده کن.`,`با ${other} و مایع کافی، غذا را روی شعله کم بپز؛ هر چند دقیقه غلظت را بررسی کن و در صورت لزوم آب گرم بیفزا.`,`وقتی اجزا نرم و سس یکدست شد، چاشنی ترش یا ادویه را در انتها تنظیم کن؛ خام‌ماندن گوشت یا حبوبات مجاز نیست.`],
 roast:[`فر را روی حدود ۱۹۰ درجه سانتی‌گراد گرم کن؛ ${first} و ${other} را به تکه‌های هم‌اندازه آماده و با چاشنی‌ها ترکیب کن.`,`مواد را در یک لایه روی سینی پخش کن و در میانه پخت جابه‌جا کن تا سطحشان طلایی و داخلشان پخته شود.`,`قبل از سرو، پخت مرکز تکه‌های گوشتی یا ماهی را با دماسنج بررسی کن و آب‌غوره یا سس را تازه اضافه کن.`],
 skillet:[`مواد را آماده کن؛ ${first} را در تابه داغ با کمی روغن به‌آرامی تفت بده و ${other} را در زمان مناسب اضافه کن.`,`حرارت را طوری نگه دار که مواد نسوزند؛ در صورت وجود سس یا سبزی، آن را بعد از تغییر رنگ مواد اصلی اضافه کن.`,`تا رسیدن به بافت و پخت ایمن ادامه بده و پیش از خاموش‌کردن شعله، طعم و غلظت سس را تنظیم کن.`],
 soup:[`سبزی و ${first} و ${other} را پاک و خرد کن؛ اگر حبوبات خشک دارد از قبل بپز.`,`مواد را با آب یا آبِ مرغ در قابلمه بریز و آهسته بجوشان؛ مواد دیرپز را زودتر و سبزی‌های لطیف را دیرتر اضافه کن.`,`پس از نرم‌شدن اجزا، غلظت را تنظیم کن و در صورت لزوم بخشی از سوپ را پوره کن؛ بسیار داغ سرو نکن.`],
 bake:[`فر را تا حدود ۱۸۰ درجه گرم کن و ظرف نسوز را آماده کن؛ ${first} و ${other} را قبل از چیدن مطابق نیاز غذا نیم‌پز یا خرد کن.`,`مواد را لایه‌لایه یا یکنواخت در ظرف بچین؛ روی آن را در صورت نیاز با پنیر یا سس پوشش بده.`,`تا پخت کامل مرکز غذا و طلایی شدن سطح بپز؛ چند دقیقه استراحت بده تا برش زدن آسان شود.`],
 fritter:[`مواد خام را آماده و ریز خرد یا رنده کن؛ آب اضافی ${first} و ${other} را تا حد امکان بگیر.`,`مایه را با تخم‌مرغ یا چسباننده موجود در فهرست ترکیب کن و به قطعات یک‌اندازه شکل بده.`,`دو طرف را با حرارت متوسط بپز تا مغزپخت شود؛ اگر گوشت دارد دمای مرکز را حتماً بررسی کن.`],
 pasta:[`در قابلمه بزرگی آب را بجوشان و ${first} یا پاستای دستور را تا بافت مناسب بپز؛ کمی از آب پخت را کنار بگذار.`,`${other} و مواد سس را در تابه جداگانه با حرارت متوسط آماده کن و چاشنی‌ها را با مقدار کنترل‌شده بیفزا.`,`پاستا را با سس مخلوط کن؛ با آبِ پخت غلظت را تنظیم کن و در صورت نیاز با سبزی یا پنیر سرو کن.`],
 wrap:[`مواد میانی مانند ${first} و ${other} را آماده کن؛ گوشت خام باید پیش از پیچیدن کاملاً پخته و خنک‌شده باشد.`,`نان ترتیلا را اندکی گرم کن؛ مواد میانی، سس و سبزی‌های شسته را در مرکز آن قرار بده.`,`دو طرف نان را جمع کن و محکم بپیچ؛ اگر پنیر دارد کمی روی تابه گرم کن و بلافاصله سرو کن.`],
 salad:[`سبزی‌ها را بشوی و خشک کن؛ ${first} و ${other} را خرد کن و غلات، حبوبات یا پروتئین لازم را جداگانه بپز.`,`اجزا را پس از خنک شدن پختنی‌ها در کاسه بریز؛ سس را جدا با چاشنی‌های فهرست مخلوط کن.`,`سس را درست پیش از سرو اضافه کن تا سالاد آب نیندازد؛ مواد پخته و خام را بهداشتی نگه دار.`],
 curry:[`پیاز و ادویه کاری را با مقدار کمی روغن تفت بده؛ ${first} و ${other} را متناسب با زمان پخت آماده کن.`,`گوجه یا شیر نارگیلِ فهرست را اضافه کن؛ با شعله ملایم بجوشان تا مواد نرم شوند و سس غلیظ شود.`,`غلظت، تندی و نمک را تنظیم کن؛ گوشت، ماهی یا حبوبات حتماً باید کاملاً پخته باشند.`],
 pie:[`مواد میانی ${first} و ${other} را جداگانه بپز و آب اضافی را کم کن؛ فر را روی ۱۹۰ درجه گرم کن.`,`مواد را در ظرف نسوز بریز، با لایه سیب‌زمینی یا خمیرِ موجود در مواد بپوشان و سطح آن را صاف کن.`,`در فر بپز تا مرکز داغ و سطح طلایی شود؛ پیش از سرو چند دقیقه استراحت بده.`],
 bowl:[`${first} و ${other} را متناسب با نوعشان جداگانه بپز یا خرد کن؛ پروتئین خام را کامل بپز.`,`غله، حبوبات و سبزی‌ها را در کاسه‌های جدا بچین؛ مواد گرم را از سبزی‌های سرد جدا نگه دار.`,`با چاشنی دلخواه از مواد فهرست ترکیب کن و تازه سرو کن.`],
 noodle:[`نودل یا رشته برنجی را طبق زمان بسته آماده کن؛ ${first} و ${other} را خرد و خشک کن.`,`مواد را در تابه گود با حرارت نسبتاً زیاد و روغن کم سریع تفت بده و سس را در پایان اضافه کن.`,`رشته را با مخلوط تابه زیرورو کن تا گرم و یکدست شود؛ بلافاصله سرو کن.`],
 sandwich:[`مواد داخل ساندویچ از جمله ${first} و ${other} را آماده کن؛ گوشت و تخم‌مرغ باید پیش از استفاده کاملاً پخته باشند.`,`نان را در صورت تمایل کمی گرم کن و لایه‌ای نازک از سس بزن؛ محتویات و سبزی‌های شسته را روی نان بچین.`,`نان را ببند و اگر دستور از پنیر آب‌شونده استفاده می‌کند چند دقیقه روی تابه گرم کن؛ تازه سرو کن.`],
 egg:[`مواد همراهِ ${first} و ${other} را خرد کن و در صورت نیاز از قبل بپز؛ تخم‌مرغ را جدا در کاسه تمیز بشکن.`,`سبزیجات را مختصر تفت بده، سپس تخم‌مرغ را اضافه کن و حرارت را کم کن تا کف و روی آن نسوزد.`,`آن‌قدر ادامه بده تا سفیده و زرده برای مصرف ایمن کاملاً بسته شوند؛ با سبزی تازه سرو کن.`],
 fish:[`ماهی را با دستمال خشک کن و ${other} و چاشنی‌های دستور را آماده کن؛ تا زمان پخت آن را سرد نگه دار.`,`با روش بخارپز یا تابه‌ای و حرارت ملایم بپز؛ زمان به ضخامت قطعه بستگی دارد، نه فقط دقیقه ثابت.`,`دمای مرکز را به حد ایمن برسان و در پایان چاشنی ترش را اضافه کن؛ از تماس غذای پخته با سطح ماهی خام جلوگیری کن.`],
 snack:[`مواد ${first} و ${other} را به اندازه مناسب آماده و در صورت نیاز جداگانه بپز یا تفت بده.`,`مواد را با چاشنی‌ها مخلوط و به اندازه‌های کوچک تقسیم کن؛ اگر قرار است برشته شود حرارت را متوسط نگه دار.`,`بافت و طعم را بررسی کن؛ خوراکی‌های دارای شیر یا تخم‌مرغ را در دمای محیط طولانی نگهداری نکن.`]
 };
 const recipe=selected[mode]; if(!recipe)throw Error('Unsupported cooking method '+mode);
 const steps=[preface,...recipe];
 return steps.map((body,i)=>({title:`مرحله ${i+1}`,body}));
}
export const RESEARCHED_RECIPES:Recipe[]=ROWS.trim().split('\\n').map((line,i)=>{
 const [title,cats,pre,cook,raw,mode,url,reference]=line.split('|');
 if(!title||!cats||!raw||!mode||!url||!reference)throw Error('Invalid researched catalog row '+i);
 const ingredients:RecipeIngredient[]=raw.split(',').map(fragment=>{
  const [id,rawAmount]=fragment.split('/');if(!id||!rawAmount||!BY_ID.has(id))throw Error(`${title}: missing ingredient ${id}`);
  const unit:Unit=fluids.has(id)?'ml':units.has(id)&&Number(rawAmount)<=12?'pcs':'g';
  return {ingredientId:id,quantity:{amount:Number(rawAmount),unit},essential:true};
 });
 const special= SPECIAL[title];
 const steps:Recipe['steps']=special?special.map((body,j)=>({title:`مرحله ${j+1}`,body})):makeSteps(mode,ingredients,title);
 const poultry=ingredients.some(x=>['chicken','chicken_thigh','chicken_leg','chicken_mince','turkey','ground_turkey'].includes(x.ingredientId));
 const groundMeat=ingredients.some(x=>['ground_beef','ground_lamb'].includes(x.ingredientId));
 const seafood=ingredients.some(x=>['fish','white_fish','salmon','cod','shrimp','sardine'].includes(x.ingredientId));
 const last=steps[steps.length-1]!;
 if(poultry)last.safetyNote='مرغ و بوقلمون خام را تا دمای داخلی دست‌کم ۷۴ درجه سانتی‌گراد بپز و از دماسنج غذایی استفاده کن.';
 else if(groundMeat)last.safetyNote='گوشت چرخ‌کرده را تا دمای داخلی دست‌کم ۷۱ درجه سانتی‌گراد بپز.';
 else if(seafood)last.safetyNote='ماهی باید تا دمای داخلی حداقل ۶۳ درجه سانتی‌گراد پخته شود.';
 const isAdaptation=/adaptation|جایگزین|بدون الکل/i.test(reference+' '+title);
 return {id:`recipe-${String(i+173).padStart(3,'0')}`,title,
  description:`طرح تدوینی ${title} با ${ingredients.slice(0,3).map(x=>say(x.ingredientId)).join('، ')}؛ مقادیر برآوردی و نیازمند بازبینی آشپزی.`,
  categories:Array.from(new Set(cats.split('').map(c=>C[c]!).filter(Boolean))),
  servings:3,prepMinutes:Number(pre),cookMinutes:Number(cook),
  difficulty:Number(pre)+Number(cook)>=100?'medium':'easy',ingredients,steps,contentStatus:'draft',
  provenance:{kind:isAdaptation?'editorial':'source',url,sourceScope:isAdaptation?'adaptation':url.includes('tollbit.bbcgoodfood.com')||url.includes('20064-ghaza-irani')?'collection':'recipe',sourceTitle:reference}
 };
});
'''
target.write_text(header,encoding='utf-8')
print('Compiled',len(rows),'researched recipe drafts; next',172+len(rows),'total recipes')
